// app/directory-badges.tsx: render <DirectoryBadges /> in your footer
export default async function DirectoryBadges() {
  try {
    const res = await fetch("https://feed.example.net/badge/91bb683b-04df-68e5-fea1-c01f13987d91.json", {
      next: { revalidate: 300 },
    });
    if (!res.ok) return null;
    const { badges } = await res.json();
    return <div dangerouslySetInnerHTML={{ __html: badges.join("") }} />;
  } catch {
    return null;
  }
}

// functions.php: then add the [directory_badges] shortcode to your footer
add_shortcode("directory_badges", function () {
  $response = wp_remote_get("https://feed.example.net/badge/91bb683b-04df-68e5-fea1-c01f13987d91.html", ["timeout" => 3]);
  if (is_wp_error($response) || wp_remote_retrieve_response_code($response) !== 200) {
    return "";
  }
  return wp_remote_retrieve_body($response);
});

# In the server block of ledgerly.test
location = /directory-badges {
  internal;
  proxy_pass https://feed.example.net/badge/91bb683b-04df-68e5-fea1-c01f13987d91.html;
  proxy_ssl_server_name on;
  proxy_set_header Accept-Encoding "";
}

# In the location that serves your pages
ssi on;

# In the page, where the badges should appear:
# <!--# include virtual="/directory-badges" -->

